        'header.menu.partner_dashboard' => ['header', 'Menu: partner dashboard', 'Partner dashboard', 'భాగస్వామి డాష్‌బోర్డ్'],
        'header.menu.account' => ['header', 'Menu: account', 'My account', 'నా ఖాతా'],
        'header.menu.help' => ['header', 'Menu: help', 'Help Center', 'సహాయ కేంద్రం'],
        'account.delete.title' => ['account', 'Page heading', 'Delete your 1CallFix account', 'మీ 1CallFix ఖాతాను తొలగించండి'],
        'account.delete.intro' => ['account', 'Line under the heading', 'You can delete your account from the app or from this page. Here is what happens.', 'మీ ఖాతాను యాప్ నుండి లేదా ఈ పేజీ నుండి తొలగించవచ్చు. ఏమి జరుగుతుందో ఇక్కడ ఉంది.'],
        'account.delete.steps_title' => ['account', 'Steps heading', 'How to delete', 'ఎలా తొలగించాలి'],
        'account.delete.step_customer' => ['account', 'Steps: customer app', '1CallFix app: tap the menu (☰) at the top → Account → Delete my account.', '1CallFix యాప్: పైన మెనూ (☰) → ఖాతా → నా ఖాతాను తొలగించు నొక్కండి.'],
        'account.delete.step_partner' => ['account', 'Steps: rider and partner apps', 'Rider app or Partner app: tap More at the bottom → Delete my account.', 'రైడర్ లేదా పార్ట్‌నర్ యాప్: కింద More → నా ఖాతాను తొలగించు నొక్కండి.'],
        'account.delete.step_web' => ['account', 'Steps: website', 'Website: sign in, then open this page and tap the button below.', 'వెబ్‌సైట్: సైన్ ఇన్ చేసి, ఈ పేజీ తెరిచి కింది బటన్ నొక్కండి.'],
        'account.delete.step_help' => ['account', 'Steps: no access', 'Cannot sign in? Call or write to Help from the Help Center and we will delete it for you.', 'సైన్ ఇన్ కాలేదా? సహాయ కేంద్రం ద్వారా మాకు కాల్ చేయండి లేదా రాయండి, మేము తొలగిస్తాము.'],
        'account.delete.what_title' => ['account', 'What happens heading', 'What happens', 'ఏమి జరుగుతుంది'],
        'account.delete.what_1' => ['account', 'What happens: 1 (:days)', 'Sign-in stops at once. Your name, phone, email and addresses are erased after :days days. Call Help before then to undo it.', 'సైన్ ఇన్ వెంటనే ఆగిపోతుంది. మీ పేరు, ఫోన్, ఈమెయిల్, చిరునామాలు :days రోజుల తర్వాత తొలగించబడతాయి. అంతకు ముందు సహాయానికి కాల్ చేస్తే తిరిగి తెరవవచ్చు.'],
        'account.delete.what_2' => ['account', 'What happens: 2', 'Bills and past orders are kept without your name, because tax law needs them.', 'పన్ను చట్టం కోసం బిల్లులు, పాత ఆర్డర్లు మీ పేరు లేకుండా ఉంచబడతాయి.'],
        'account.delete.what_3' => ['account', 'What happens: 3', 'Promo and referral credit is lost. Use your wallet money first, or ask Help for a refund.', 'ప్రోమో, రెఫరల్ క్రెడిట్ పోతుంది. ముందుగా వాలెట్ డబ్బు వాడండి లేదా రీఫండ్ కోసం సహాయాన్ని అడగండి.'],
        'account.delete.what_partner' => ['account', 'What happens: partners', 'Riders and partners: we settle your dues and payouts first, then close the account.', 'రైడర్లు, పార్ట్‌నర్లు: ముందుగా మీ బకాయిలు, చెల్లింపులు సెటిల్ చేసి, తర్వాత ఖాతాను మూసివేస్తాము.'],
        'account.delete.sign_in' => ['account', 'Button when signed out', 'Sign in to delete', 'తొలగించడానికి సైన్ ఇన్ చేయండి'],
        'account.delete.confirm' => ['account', 'Tick box', 'I understand. Delete my account.', 'నాకు అర్థమైంది. నా ఖాతాను తొలగించు.'],
        'account.delete.confirm_needed' => ['account', 'Error when the box is not ticked', 'Tick the box to confirm.', 'నిర్ధారించడానికి బాక్స్ టిక్ చేయండి.'],
        'account.delete.button' => ['account', 'Button: customer', 'Delete my account', 'నా ఖాతాను తొలగించు'],
        'account.delete.button_partner' => ['account', 'Button: partner', 'Send delete request', 'తొలగింపు అభ్యర్థన పంపండి'],
        'account.delete.block_wallet' => ['account', 'Blocked: wallet money (:amount)', 'You have :amount in your wallet. Use it or ask Help for a refund first.', 'మీ వాలెట్‌లో :amount ఉంది. ముందుగా వాడండి లేదా రీఫండ్ కోసం సహాయాన్ని అడగండి.'],
        'account.delete.block_open' => ['account', 'Blocked: open booking or order', 'You have a booking, order or parcel still open. Delete after it is finished or cancelled.', 'మీకు ఇంకా తెరిచి ఉన్న బుకింగ్, ఆర్డర్ లేదా పార్సిల్ ఉంది. అది పూర్తయిన లేదా రద్దైన తర్వాత తొలగించండి.'],
        'account.delete.done' => ['account', 'After closing (:days)', 'Your account is closed. Your details will be erased in :days days.', 'మీ ఖాతా మూసివేయబడింది. మీ వివరాలు :days రోజుల్లో తొలగించబడతాయి.'],
        'account.delete.requested' => ['account', 'After a partner request', 'Request sent. We will settle your dues and payouts, then close the account.', 'అభ్యర్థన పంపబడింది. మీ బకాయిలు, చెల్లింపులు సెటిల్ చేసి ఖాతాను మూసివేస్తాము.'],
        'account.delete.pending' => ['account', 'Partner: request already sent', 'Your delete request is waiting for our team.', 'మీ తొలగింపు అభ్యర్థన మా బృందం వద్ద ఉంది.'],
        'account.delete.link' => ['account', 'Link on the Account page', 'Delete my account', 'నా ఖాతాను తొలగించు'],
        'app.rate' => ['header', 'Android apps only: rate the app on the Play Store (customer menu + partner More tab)', 'Rate & review', 'రేటింగ్ & రివ్యూ ఇవ్వండి'],
        'header.menu.logout' => ['header', 'Menu: log out', 'Log out', 'లాగ్ అవుట్'],
        'header.cart' => ['header', 'Cart icon (screen readers)', 'Cart', 'కార్ట్'],

        'search.products' => ['header', 'Search box: shop items group', 'Shop items', 'షాప్ వస్తువులు'],
        'search.shops' => ['header', 'Search box: shops group', 'Shops', 'షాపులు'],
        'search.voice_start' => ['header', 'Search box: mic button (tooltip, screen readers)', 'Search by voice', 'వాయిస్‌తో వెతకండి'],
        'search.voice_listening' => ['header', 'Search box: while the mic is listening', 'Listening… say a service, like “AC repair”', 'వింటున్నాం… “AC repair” లాంటి సర్వీస్ పేరు చెప్పండి'],
        'search.voice_failed' => ['header', 'Search box: nothing was heard', 'Didn’t catch that. Tap the mic and try again.', 'అర్థం కాలేదు. మైక్ నొక్కి మళ్లీ ప్రయత్నించండి.'],
        'search.voice_blocked' => ['header', 'Search box: microphone not allowed', 'Microphone is blocked. Allow it for this site in your browser settings.', 'మైక్రోఫోన్ బ్లాక్ అయింది. బ్రౌజర్ సెట్టింగ్స్‌లో ఈ సైట్‌కు అనుమతించండి.'],
        'address_map.search' => ['address_map', 'Search box above the map', 'Search your area, street or building', 'మీ ఏరియా, వీధి లేదా బిల్డింగ్ వెతకండి'],
        'address_map.find' => ['address_map', 'Search button', 'Find', 'వెతుకు'],
        'address_map.hint' => ['address_map', 'Line under the map', 'Move the map so the red pin sits on your door. Street, city and PIN fill in by themselves; check and correct them.', 'ఎర్ర పిన్ మీ ఇంటి గుమ్మం మీద ఉండేలా మ్యాప్‌ను జరపండి. వీధి, ఊరు, పిన్ కోడ్ వాటంతట అవే నిండుతాయి; ఒకసారి చూసి సరిచేయండి.'],
        'address_map.not_found' => ['address_map', 'Search found nothing', 'Couldn’t find that place. Try a nearby landmark, or move the map.', 'ఆ చోటు దొరకలేదు. దగ్గర్లోని గుర్తు వెతకండి లేదా మ్యాప్‌ను జరపండి.'],
        'address_map.outside' => ['address_map', 'Pin outside every service area', 'We don’t serve this exact spot yet. Move the pin to your address, or choose another area at the top.', 'ఈ చోటుకు ఇంకా మా సేవ లేదు. పిన్‌ను మీ చిరునామాకు జరపండి, లేదా పైన వేరే ఏరియా ఎంచుకోండి.'],
